  "help.survivalMonths": "ᱛᱤᱱᱟᱹᱜ ᱜᱷᱟᱹᱲᱤᱡ ᱛᱚᱨᱚᱞ ᱵᱟᱧᱪᱟᱣ ᱟᱨ ᱱᱟᱦᱟᱜ ᱯᱷᱨᱤ ᱠᱮᱥ ᱫᱚ ᱢᱟᱹᱦᱤᱛ ᱡᱩᱞᱩᱜ ᱠᱚᱵᱚᱡᱽ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ ᱡᱩᱫᱤ ᱛᱮᱦᱮᱧ ᱟᱹᱭᱫᱟᱹᱨ ᱵᱚᱱᱫᱚ ᱞᱮᱱᱠᱷᱟᱱ᱾",
  "help.emergencyReserve": "ᱢᱟᱹᱦᱱᱟ ᱫᱟᱭᱤᱠ ᱠᱚ, ᱱᱤᱨᱵᱷᱟᱨᱤᱭᱟᱹ ᱠᱚ ᱟᱨ ᱪᱷᱟᱯ ᱨᱮᱭᱟᱜ ᱞᱮᱠᱟᱛᱮ ᱥᱚᱞᱦᱟ ᱟᱠᱟᱱ ᱴᱟᱠᱟ ᱵᱟᱯᱷᱟᱨ᱾ ᱚᱠᱛᱚ ᱥᱟᱶ ᱥᱟᱶᱛᱮ ᱜᱮᱯ ᱵᱚᱱᱫᱚ ᱨᱮᱭᱟᱜ ᱡᱚᱥ ᱢᱮ ᱾",
  "help.monthlyBurden": "ᱮᱠᱴᱤᱵᱷ ᱵᱤᱞ ᱠᱷᱚᱱ ᱪᱟᱸᱫᱚ ᱯᱤᱪᱷᱤ ᱢᱚᱴᱟ ᱢᱩᱴ ᱵᱟᱹᱠᱛᱤ (ᱪᱟᱦᱱᱟ ᱯᱤᱪᱷᱤ, ᱯᱩᱱ ᱪᱟᱸᱫᱚ ᱯᱤᱪᱷᱤ ÷ ᱓, ᱥᱮᱨᱢᱟ ᱯᱤᱪᱷᱤ ÷ ᱑᱒, ᱮᱢᱟᱱ)᱾",
  "help.paycheckFlow": "ᱵᱮᱛᱚᱱ ᱢᱟᱭᱱᱟᱥ ᱴᱷᱟᱹᱣᱠᱟᱹ ᱵᱤᱞ (ᱵᱷᱟᱲᱟ, () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }s, ᱵᱤᱢᱟ) ᱢᱟᱭᱱᱟᱥ ᱞᱮᱵᱽᱲᱮᱡ ᱵᱤᱞ (ᱠᱟᱨᱰ, ᱥᱟᱵᱽᱥ)᱾ ᱪᱮᱫ ᱵᱟᱹᱠᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱚᱱᱟ ᱫᱚ ᱯᱷᱨᱤ ᱠᱮᱥ ᱠᱟᱱᱟ ᱾",
  "help.lendingFlexible": "ᱞᱮᱵᱽᱲᱮᱡ: ᱡᱟᱦᱟᱸ ᱚᱠᱛᱚ ᱨᱮ ᱡᱟᱦᱟᱱ ᱯᱮᱢᱮᱱᱴ ᱨᱮᱠᱚᱨᱰ ᱢᱮ — ᱟᱫᱷᱟ ᱥᱮ ᱯᱩᱨᱟᱹ ᱾ ᱪᱟᱸᱫᱚ ᱯᱤᱪᱷᱤ: ᱢᱤᱫ ᱠᱤᱥᱟᱹᱬ ᱥᱮᱰᱭᱩᱞ ᱯᱟᱧᱡᱟᱭ ᱢᱮ ᱾ ᱢᱤᱫ ᱜᱚᱱᱚᱝ: ᱢᱤᱫ ᱡᱚᱥ ᱢᱟᱹᱦᱤᱛ, ᱮᱢᱚᱜ ᱢᱮ ᱡᱚᱠᱷᱚᱱ ᱟᱢ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ᱾",
  "help.pressureWeight": "ᱥᱟᱱᱟᱢ ᱵᱤᱞ ᱠᱷᱚᱱ ᱪᱟᱸᱫᱚ ᱟᱱᱩᱠᱩᱞ: ᱴᱟᱠᱟ ᱫᱚᱦᱲᱟ ᱛᱟᱞᱟ (ᱡᱮᱞᱠᱟ ₹3,000 ᱯᱩᱱ ᱪᱟᱸᱫᱚ → ₹1,000/ᱪᱟᱸᱫᱚ)᱾ ᱢᱤᱫ ᱫᱷᱟᱣ ᱵᱤᱞ ᱨᱮ ᱯᱩᱨᱟᱹ ᱴᱟᱠᱟ ᱵᱮᱵᱷᱟᱨᱚᱜᱼᱟ ᱾ ᱥᱩᱢᱩᱝ ᱟᱢᱟᱜ ᱵᱟᱧᱪᱟᱣ ᱟᱠᱟᱱ ᱵᱤᱞ ᱠᱚ ᱜᱮ — ᱪᱮᱫ ᱦᱚᱸ ᱢᱟᱲᱟᱝ ᱨᱮ ᱵᱟᱝ ᱯᱮᱨᱮᱡ ᱟᱠᱟᱱᱟ ᱾",
  "help.openBalance": "ᱱᱤᱛ ᱦᱚᱸ ᱮᱠᱴᱤᱵᱷ ᱵᱤᱞ ᱨᱮ ᱢᱩᱴ ᱵᱟᱹᱨᱤ ᱢᱮᱱᱟᱜᱼᱟ (ᱪᱟᱦᱱᱟ ᱵᱚᱛᱚᱨ ᱞᱮᱠᱟ ᱵᱟᱝ)᱾",
  "help.dueThisMonth": "ᱱᱤᱛᱚᱜ ᱠᱮᱞᱮᱱᱰᱟᱨ ᱪᱟᱸᱫᱚ ᱨᱮ ᱢᱤᱫ ᱢᱟᱹᱦᱤᱛ ᱥᱟᱶ ᱵᱤᱞ ᱠᱚ ᱚᱠᱟ ᱫᱚ ᱱᱤᱛ ᱦᱚᱸ ᱯᱩᱨᱟᱹ ᱵᱟᱝ ᱮᱢ ᱟᱠᱟᱱᱟ ᱾",
  "help.freeAfterDues": "ᱵᱟᱨᱭᱟ ᱟᱨ ᱮᱠᱴᱤᱵᱷ ᱵᱤᱞ ᱠᱷᱚᱱ ᱟᱹᱭᱫᱟᱹᱨ ᱢᱟᱭᱱᱟᱥ ᱟᱱᱩᱢᱟᱱ ᱪᱟᱸᱫᱚ ᱵᱟᱹᱠᱛᱤ ᱾",
  "help.dueHeatmap": "ᱫᱚᱥᱟᱨ ᱯᱩᱱ ᱦᱟᱴ ᱨᱮ ᱛᱤᱱᱟᱹᱜ ᱵᱤᱞ ᱵᱟᱹᱠᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱟᱨ ᱚᱱᱟ ᱨᱮᱭᱟᱜ ᱢᱩᱴ ᱴᱟᱠᱟ ᱾",
  "help.debtTrend": "ᱢᱟᱨᱮ ᱟᱨ ᱱᱟᱶᱟ ᱪᱟᱸᱫᱚ ᱛᱟᱞᱟ ᱨᱮ ᱢᱩᱴ ᱚᱯᱷᱚᱱ ᱵᱮᱞᱮᱱᱥ ᱨᱮ ᱵᱚᱫᱚᱞ ᱟᱞᱮ ᱴᱷᱮᱱ ᱥᱱᱮᱯᱥᱚᱴ ᱢᱮᱱᱟᱜᱼᱟ ᱾",
  "help.chitInstallments": "ᱵᱤᱥᱛᱤ ᱢᱟᱨᱟᱝ ᱪᱤᱴ ᱠᱚ ᱫᱚ ᱥᱚᱢᱟᱱ ᱪᱟᱸᱫᱚ ᱥᱮᱭᱟᱨ ᱠᱚ ᱵᱮᱵᱷᱟᱨᱟ (ᱜᱚᱱᱚᱝ ÷ ᱪᱟᱸᱫᱚ)᱾ ᱛᱤᱱᱟᱹᱜ ᱜᱟᱱ ᱜᱟᱫᱮᱞ ᱠᱚᱢᱚᱜ ᱠᱟᱱ ᱠᱤᱥᱟᱹᱬ ᱠᱚ ᱵᱮᱵᱷᱟᱨᱟ (ᱵᱟᱹᱲᱛᱤ ᱞᱚᱜᱚᱱ, ᱠᱚᱢ ᱛᱟᱭᱚᱢ)᱾ ᱟᱢᱟᱜ ᱜᱟᱫᱮᱞ ᱥᱟᱶ ᱢᱤᱞᱟᱹᱣ ᱞᱮᱠᱟᱱ ᱵᱟᱪᱷᱟᱣ ᱢᱮ᱾",
  "help.chitMonthsPaid": "ᱟᱢ ᱛᱤᱱᱟᱹᱜ ᱜᱟᱱ ᱤᱱᱥᱴᱚᱞᱢᱮᱱᱴ ᱮᱢ ᱠᱮᱫᱟᱢ ᱾ ᱡᱩᱫᱤ ᱟᱢ ᱔᱖ ᱮᱢ ᱠᱮᱫᱟᱢ, ᱟᱢ ᱱᱤᱛᱚᱜ ᱔᱗ ᱪᱟᱸᱫᱚ ᱨᱮ ᱢᱮᱱᱟᱢᱟ ᱾ ᱱᱚᱣᱟ ᱫᱚ ᱵᱟᱹᱠᱛᱤ ᱴᱟᱠᱟ ᱟᱨ ᱪᱟᱸᱫᱚ ᱮᱞ ᱴᱷᱟᱹᱣᱠᱟᱹ ᱮᱫᱟᱭ ᱾",
  "help.chitPayoutReceived": "ᱟᱢ ᱪᱤᱴ ᱦᱟᱛᱟᱣ ᱠᱟᱛᱮ ᱥᱟᱹᱨᱤ ᱴᱟᱠᱟ ᱧᱟᱢ ᱠᱮᱫᱟᱢ (ᱡᱮᱞᱠᱟ ₹4,43,000)᱾ ᱟᱞᱮ ᱱᱚᱣᱟ ᱠᱷᱚᱱ ᱱᱤᱞᱟᱢᱤ ᱪᱷᱩᱴ ᱞᱮ ᱠᱟᱹᱢᱤᱭᱟ - ᱟᱢ ᱪᱷᱩᱴ ᱟᱴᱠᱟᱨ ᱨᱮᱭᱟᱜ ᱞᱟᱹᱠᱛᱤ ᱵᱟᱹᱱᱩᱜᱼᱟ ᱾",
  "help.chitForeman": "ᱥᱟᱯᱲᱟᱣᱤᱭᱟᱹ ᱠᱚᱢᱤᱥᱚᱱ, ᱪᱤᱴ ᱜᱚᱱᱚᱝ ᱨᱮᱭᱟᱜ ᱕% ᱞᱮᱠᱟ, ᱟᱢ ᱴᱟᱠᱟ ᱧᱟᱢ ᱠᱟᱛᱮ ᱜᱚᱢᱞᱟ ᱠᱷᱚᱱ ᱦᱟᱛᱟᱣ ᱦᱩᱭᱩᱜᱼᱟ ᱾",
  "help.chitDiscount": "ᱱᱤᱞᱟᱢᱤ ᱨᱮ ᱟᱢ ᱫᱚ ᱯᱩᱨᱟᱹ ᱪᱤᱴ ᱜᱚᱱᱚᱝ ᱠᱷᱚᱱ ᱠᱚᱢ ᱮᱢ ᱟᱝᱜᱚᱪᱟ - ᱱᱚᱣᱟ ᱪᱷᱩᱴ ᱫᱚ ᱮᱴᱟᱜ ᱨᱟᱹᱥᱤᱭᱟᱹ ᱠᱚ ᱥᱟᱶ ᱦᱟᱹᱴᱤᱧᱚᱜᱼᱟ ᱾ ᱟᱢ ᱫᱚ ᱯᱩᱨᱟᱹ ᱪᱤᱴ ᱴᱟᱠᱟ ᱴᱟᱠᱟ ᱛᱮ ᱛᱤᱥ ᱦᱚᱸ ᱵᱟᱢ ᱧᱟᱢᱟ ᱾",
  "help.chitAdvisor": "ᱪᱟᱸᱫᱚ ᱛᱩᱞᱟᱹ ᱡᱚᱠᱷᱚᱱ ᱟᱢ ᱪᱤᱴ ᱦᱟᱛᱟᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ: ᱟᱱᱢᱟᱱ ᱪᱷᱩᱴ, ᱯᱷᱚᱨᱢᱮᱱ ᱛᱟᱭᱚᱢ ᱯᱮᱭᱟᱣᱩᱴ, ᱟᱢᱟᱜ ᱮᱴᱟᱜ ᱵᱤᱞ ᱚᱱᱟ ᱪᱟᱸᱫᱚ, ᱟᱨ ᱢᱟᱠᱥ ᱞᱚᱥ ᱟᱢ ᱟᱝᱜᱚᱪ ᱞᱟᱹᱜᱤᱫ ᱮᱢ ᱥᱟᱱᱟᱭᱟ᱾",
  "help.chitMaxLoss": "ᱟᱞᱮ ᱟᱢᱟᱜ ᱠᱟᱢᱟᱣ, ᱪᱟᱸᱫᱚ ᱵᱟᱹᱠᱛᱤ, ᱠᱷᱩᱞᱟᱹ ᱨᱤᱱ, ᱵᱟᱹᱲᱛᱤ ᱵᱟᱹᱠᱛᱤ ᱵᱤᱞ, ᱟᱨ ᱵᱟᱧᱪᱟᱣ ᱠᱷᱚᱱ ᱰᱷᱮᱨ ᱠᱷᱚᱱ ᱰᱷᱮᱨ ᱦᱟᱹᱱ ᱞᱮ ᱥᱚᱞᱦᱟᱭᱮᱫᱟ — ᱢᱤᱫ ᱴᱷᱟᱹᱣᱠᱟᱹ % ᱫᱚ ᱵᱟᱝ ᱾ ᱞᱚᱜᱚᱱ ᱦᱟᱛᱟᱣ ᱫᱚ ᱟᱹᱰᱤ ᱜᱷᱟᱹᱲᱤᱡ ᱱᱚᱣᱟ ᱠᱷᱚᱱ ᱦᱚᱸ ᱵᱟᱹᱲᱛᱤ ᱜᱮᱭᱟ; ᱛᱟᱭᱚᱢ ᱪᱟᱸᱫᱚ ᱨᱮ ᱥᱟᱫᱷᱟᱨᱚᱱ ᱠᱚᱢ ᱜᱚᱱᱚᱝ ᱦᱩᱭᱩᱜᱼᱟ ᱾",
  "help.loanExtraTiming": "ᱦᱤᱡᱩᱜ ᱠᱟᱱ ᱪᱟᱸᱫᱚ ᱩᱫᱩᱜᱚᱜ ᱠᱟᱱᱟ: ᱛᱤᱱ ᱨᱮ ᱮᱴᱟᱜ ᱵᱤᱞ ᱠᱚ ᱦᱟᱹᱞᱠᱟ ᱛᱟᱦᱮᱱᱟ ᱚᱱᱟᱛᱮ ᱟᱢ ᱱᱚᱶᱟ ᱨᱤᱱ ᱵᱟᱹᱲᱛᱤ ᱮᱢ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ, ᱟᱨ ᱦᱟᱢᱟᱞ ᱪᱟᱸᱫᱚ ᱛᱤᱱ ᱨᱮ ᱟᱢ ᱠᱚᱢ ᱠᱷᱚᱱ ᱠᱚᱢ ᱛᱟᱦᱮᱱ ᱦᱩᱭᱩᱜ ᱛᱟᱢᱟ᱾",
  "help.incomeEntryBasis": "ᱴᱮᱠ-ᱚᱲᱟᱜ ᱢᱤᱞᱟᱹᱣ ᱢᱮ ᱚᱠᱟ ᱦᱟᱥᱟ ᱟᱢᱟᱜ ᱵᱮᱝᱠ ᱨᱮ ᱴᱮᱠᱥ ᱛᱟᱭᱚᱢ, () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }, ᱟᱨ ᱴᱷᱟᱹᱣᱠᱟᱹ ᱠᱚᱢᱟᱣ — ᱪᱷᱟᱯ ᱟᱨ ᱯᱷᱨᱤ-ᱠᱮᱥ ᱮᱞᱠᱷᱟ ᱞᱟᱹᱜᱤᱫ ᱥᱚᱨᱮᱥ ᱾ ᱜᱽᱨᱚᱥ ᱫᱚ ᱥᱩᱢᱩᱝ ᱜᱮ ᱞᱟᱹᱠᱛᱤᱭᱟᱱᱟ ᱡᱚᱠᱷᱚᱱ ᱟᱢ ᱮᱢ ᱟᱠᱟᱫ ᱡᱚᱛᱚ ᱮᱞ ᱜᱮ ᱯᱨᱤ-ᱴᱮᱠᱥ ᱦᱩᱭᱩᱜ-ᱟ; ᱯᱷᱨ��� ᱠᱮᱥ ᱫᱚ ᱟᱢᱟᱜ ᱥᱟᱹᱨᱤ ᱵᱮᱝᱠ ᱵᱟᱞᱮᱱᱥ ᱠᱷᱚᱱ ᱠᱚᱢ ᱧᱮᱞᱚᱜᱼᱟ ᱡᱩᱫᱤ ᱚᱲᱟᱜ ᱨᱮ ᱟᱹᱭᱫᱟᱹᱨ ᱢᱩᱴ ᱠᱷᱚᱱ ᱠᱚᱢ ᱛᱟᱦᱮᱱ ᱠᱷᱟᱱ ᱾",
  "help.householdPayerBillTag": "ᱜᱷᱟᱨᱚᱧᱡᱽ ᱢᱚᱰ ᱞᱟᱹᱜᱤᱫ ᱚᱯᱥᱚᱱᱟᱞᱺ ᱴᱮᱜᱽ ᱢᱮ ᱚᱠᱚᱭ ᱯᱩᱭᱥᱟᱹ ᱮᱢᱟᱭᱟ ᱡᱮᱢᱚᱱ ᱚᱲᱟᱜ ᱨᱮᱱ ᱫᱟᱞ ᱦᱟᱹᱴᱤᱧ ᱟᱝᱜᱤᱵᱷᱟᱨ ᱠᱚ ᱵᱚᱨᱱᱚᱱ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾ ᱢᱩᱴ ᱟᱨ ᱯᱨᱮᱥᱚᱨ ᱮᱞᱠᱷᱟ ᱥᱚᱢᱟᱱ ᱜᱮ ᱛᱟᱦᱮᱱᱟ ᱾",
