  "support.contactHint": "ᱤᱢᱮᱞ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱮᱠᱟᱣᱩᱱᱴ ᱵᱟᱝᱠᱷᱟᱱ ᱯᱨᱚᱰᱟᱠᱴ ᱠᱩᱠᱞᱤ ᱠᱚ ᱞᱟᱹᱜᱤᱫ ᱾",
