  "support.about": "ᱵᱟᱨᱮᱛᱮ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }",
  "support.aboutBody": "CommitTrack ᱵᱷᱟᱨᱚᱱ ᱚᱲᱟᱜ ᱠᱚ ᱵᱤᱞ, ᱨᱤᱱ ᱮᱢ ᱟᱨ ᱪᱟᱸᱫᱚ ᱪᱷᱟᱯ ᱴᱨᱟᱠ ᱞᱟᱹᱜᱤᱫ ᱜᱚᱲᱚ ᱮᱢᱟ ᱠᱚᱣᱟᱭ ᱾ Daloy Tech ᱦᱚᱛᱮᱛᱮ ᱛᱮᱭᱟᱨ ᱟᱠᱟᱱᱟ, Tadsaya ᱞᱟᱛᱟᱨ ᱨᱮ ᱢᱤᱫ SaaS ᱠᱚᱢᱯᱟᱱᱤ ᱾",
