  "notifications.testFail": "ᱮᱞᱟᱨᱴ ᱵᱟᱝ ᱩᱫᱩᱜ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱟᱱᱟ᱾ ᱮᱯ ᱤᱱᱥᱴᱚᱞ ᱢᱮ (ᱦᱚᱢ ᱥᱠᱨᱤᱱ ᱨᱮ ᱥᱮᱞᱮᱫ ᱢᱮ) ᱟᱨᱵᱟᱝ ᱵᱮᱵᱷᱟᱨ ᱢᱮ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }/ᱟᱲᱮ᱾",
  "notifications.testInApp": "ᱵᱤᱱᱤᱰ ᱫᱤᱱᱟᱹᱥ — ᱱᱚᱣᱟ ᱥᱟᱫᱷᱚᱱ ᱨᱮ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱠᱚ ᱠᱟᱹᱢᱤ ᱠᱟᱱᱟ ᱾",
  "notifications.installHint": "ᱴᱨᱮ ᱮᱞᱟᱨᱴ ᱞᱟᱹᱜᱤᱫᱺ ᱮᱯ ᱤᱱᱥᱴᱚᱞ ᱢᱮ (ᱦᱚᱢ ᱥᱠᱨᱤᱱ ᱨᱮ ᱥᱮᱞᱮᱫ ᱢᱮ), ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱨᱮᱭᱟᱜ ᱪᱷᱟᱹᱲ ᱢᱮ, ᱟᱨ ᱫᱤᱱᱟᱹᱥ ᱪᱟᱹᱞᱩ ᱫᱚᱦᱚᱭ ᱢᱮ᱾ ᱵᱟᱹᱠᱛᱤ ᱟᱨ ᱵᱟᱹᱠᱛᱤ ᱵᱤᱞ ᱠᱚ ᱵᱟᱰᱟᱭ ᱚᱪᱚ ᱢᱮ ᱡᱚᱠᱷᱚᱱ ᱟᱢ ᱮᱯ ᱮᱢ ᱵᱟᱹᱜᱤᱭᱟ ᱥᱮ ᱛᱤᱱᱟᱹᱜ ᱜᱟᱱ ᱴᱟᱲᱟᱝ ᱯᱤᱪᱷᱤ (() => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }/() => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    })᱾ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱦᱚᱢ-ᱥᱠᱨᱤᱱ ᱮᱯ ᱟᱭᱠᱚᱱ ᱞᱟᱹᱠᱛᱤᱜ ᱠᱟᱱᱟ — () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱴᱮᱵᱽ ᱮᱠᱞᱟ ᱵᱮᱠᱜᱨᱟᱣᱩᱱᱰ-ᱱᱚᱴᱤᱯᱷᱟᱭ ᱵᱟᱝ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ ᱾",
  "backup.fileTitle": "ᱨᱮᱫ ᱵᱮᱠᱚᱯ",
  "backup.fileSubtitle": "ᱮᱠᱥᱯᱚᱨᱴ ᱥᱮ ᱤᱢᱯᱚᱨᱴ ᱮ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    ᱱᱚᱶᱟ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱨᱮ } ᱨᱮᱫ ᱾ () ᱠᱷᱚᱱ ᱫᱚᱦᱲᱟᱭ ᱢᱮ => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱪᱮᱛᱟᱱ ᱨᱮ ᱮᱠᱟᱣᱩᱱᱴ ᱵᱮᱠᱟᱯ ᱨᱮ ᱢᱮᱱᱟᱜᱼᱟ ᱾",
  "backup.exportJson": "ᱮᱠᱥᱯᱚᱨᱴ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱵᱮᱠᱟᱯ",
  "backup.exportJsonHint": "ᱵᱤᱞ ᱠᱚ, ᱨᱤᱱ ᱮᱢᱚᱜ, ᱡᱚᱥ ᱠᱚ ᱟᱨ ᱥᱮᱴᱤᱝ ᱠᱚ ᱢᱤᱫ ᱨᱮᱫ ᱨᱮ ᱥᱟᱧᱪᱟᱣ ᱢᱮ",
