  "install.hintIos": "ᱪᱟᱹᱞᱩ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱟᱨᱵᱟᱝ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }: ᱦᱟᱹᱴᱤᱧ ᱨᱮ ᱞᱤᱱ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱦᱚᱢ ᱥᱠᱨᱤᱱ ᱨᱮ ᱥᱮᱞᱮᱫ ᱢᱮ ᱾ ᱡᱷᱤᱡᱽ ᱢᱮ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } ᱟᱢᱟᱜ ᱦᱚᱢ ᱥᱠᱨᱤᱱ ᱠᱷᱚᱱ ᱾",
  "install.hintAndroid": "ᱪᱟᱹᱞᱩ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }: ᱢᱮᱱᱩ ᱡᱷᱤᱡᱽ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱮᱯ ᱤᱱᱥᱴᱚᱞ ᱢᱮ ᱟᱨᱵᱟᱝ ᱦᱚᱢ ᱥᱠᱨᱤᱱ ᱨᱮ ᱥᱮᱞᱮᱫ ᱢᱮ ᱾",
