  "insight.free-cash-low": "Free ᱥᱟᱫᱷᱟᱨᱚᱱ ᱪᱟᱸᱫᱚ ᱫᱟᱭᱤᱠ ᱠᱚ ᱛᱟᱭᱚᱢ ᱴᱟᱠᱟ ᱫᱚ ᱥᱤᱢᱟᱹ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ (ᱫᱟᱭᱤ ᱠᱚ ᱫᱚ ᱟᱹᱭᱫᱟᱹᱨ ᱨᱮᱭᱟᱜ ᱢᱟᱨᱟᱝ ᱦᱟᱹᱴᱤᱧ ᱠᱚ ᱵᱮᱵᱷᱟᱨᱟ)᱾",
  "insight.burden-danger": "EMI-ᱥᱴᱟᱭᱤᱞ ᱵᱚᱛᱚᱨ ᱫᱚ ᱟᱹᱭᱫᱟᱹᱨ ᱥᱟᱶ ᱥᱟᱹᱜᱟᱹᱭ ᱛᱮ ᱪᱮᱛᱟᱱ ᱯᱟᱥᱱᱟᱣ ᱨᱮ ᱢᱮᱱᱟᱜᱼᱟ ᱾ ᱡᱩᱫᱤ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱷᱟᱱ ᱱᱟᱶᱟ ᱠᱚᱢᱤᱴᱢᱮᱱᱴ ᱵᱟᱹᱜᱤᱭᱟᱜ ᱢᱮ᱾",
  "insight.burden-risk": "ᱢᱟᱹᱦᱱᱟ ᱵᱤᱞ ᱵᱚᱛᱚᱨ ᱫᱚ ᱟᱹᱭᱫᱟᱹᱨ ᱥᱟᱶ ᱥᱟᱹᱜᱟᱹᱭ ᱛᱮ ᱵᱟᱹᱲᱛᱤ ᱜᱮᱭᱟ - ᱵᱤᱪᱟᱹᱨ ᱠᱷᱚᱨᱪᱟ ᱨᱮᱭᱟᱜ ᱥᱟᱠᱟᱢ ᱧᱮᱞ ᱢᱮ ᱾",
  "insight.subs-weight": "ᱥᱟᱵᱽᱥᱠᱨᱤᱯᱥᱚᱱ ᱫᱚ ᱟᱢᱟᱜ ᱵᱮᱥᱞᱟᱭᱤᱱ ᱨᱮ ᱢᱚᱴᱟ {amount}/mo ᱥᱮᱞᱮᱫᱚᱜ ᱠᱟᱱᱟ — ᱚᱠᱛᱚ ᱥᱟᱶ ᱥᱟᱶᱛᱮ ᱫᱚᱦᱲᱟ ᱠᱷᱚᱨᱚᱪ ᱡᱟᱣᱨᱟᱜ ᱠᱟᱱᱟ ᱾",
