  "insight.pressure-down": "ᱟᱢ ᱫᱚ ᱞᱟᱦᱟ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱥᱱᱮᱯᱥᱚᱴ ᱨᱮᱭᱟᱜ ᱛᱩᱞᱟᱹ ᱡᱚᱠᱷᱟ ᱨᱮ ᱵᱤᱞ ᱨᱮᱭᱟᱜ ᱪᱷᱟᱯ ᱠᱚᱢ ᱟᱠᱟᱫᱟᱢ ᱾",
  "insight.multi-overdue": "{count} ᱡᱤᱱᱤᱥ ᱠᱚ ᱫᱚ ᱢᱩᱪᱟᱹᱫ ᱮᱱᱟ — ᱯᱩᱭᱞᱩ ᱚᱱᱟ ᱠᱚ ᱯᱷᱟᱨᱪᱟ ᱞᱮᱠᱷᱟᱱ ᱥᱚᱡᱷᱮ ᱥᱚᱡᱷᱮ ᱪᱷᱟᱯ ᱠᱚᱢᱚᱜᱼᱟ ᱾",
  "insight.paying-habit": "ᱟᱢ ᱱᱤᱭᱟᱹ ᱪᱟᱸᱫᱚ ᱯᱮᱢᱮᱱᱴ ᱨᱮ {amount} ᱨᱮᱠᱚᱨᱰ ᱠᱮᱫᱟᱢ — ᱞᱮᱛᱟᱲ ᱯᱮᱢᱮᱱᱴ ᱛᱮ ᱠᱟᱹᱣᱰᱤ ᱨᱟᱱᱣᱮ ᱨᱮ ᱥᱩᱫᱷᱨᱟᱹᱣ ᱦᱩᱭᱩᱜᱼᱟ ᱾",
  "insight.overlap-week": "ᱟᱢ ᱴᱷᱮᱱ {count} ᱵᱟᱹᱠᱛᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱱᱤᱭᱟᱹ ᱦᱟᱯᱛᱟ (≈{total} ᱢᱩᱴ)—ᱥᱴᱟᱜᱽᱟᱨ ᱯᱮᱢᱮᱱᱴ ᱡᱩᱫᱤ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱷᱟᱱ ᱾",
  "insight.forecast-crunch-negative": "ᱟᱢ ᱫᱚ {month} ᱟᱰᱮ ᱯᱟᱥᱮ ᱨᱮ ᱱᱮᱜᱮᱴᱤᱵᱷ ᱯᱷᱨᱤ ᱠᱮᱥ ᱥᱟᱢᱟᱝ ᱫᱟᱯᱨᱟᱢ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ (ᱵᱟᱹᱠᱛᱤ ᱚᱱᱟ ᱪᱟᱸᱫᱚ ᱨᱮᱱᱟᱜ ᱟᱹᱭᱫᱟᱹᱨ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱜᱮᱭᱟ)᱾",
  "insight.forecast-crunch-tight": "ᱴᱟᱠᱟ ᱫᱚ ᱥᱤᱢᱟᱹ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ {month} — ᱥᱩᱢᱩᱝ ≈{free} ᱟᱱᱩᱢᱟᱱ ᱵᱟᱹᱠᱛᱤ ᱛᱟᱭᱚᱢ ᱯᱷᱨᱤ ᱾",
  "insight.subs-yearly": "ᱟᱢᱟᱜ ᱥᱟᱵᱽᱥᱠᱨᱤᱯᱥᱚᱱ ᱨᱮᱭᱟᱜ ᱜᱚᱱᱚᱝ ᱱᱤᱛᱚᱜ ᱫᱚᱨ ᱞᱮᱠᱟᱛᱮ {amount}/ᱥᱮᱨᱢᱟ ᱞᱮᱠᱟ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.emi-pct": "EMIs ᱵᱮᱵᱷᱟᱨ ᱢᱮ {percent}% ᱟᱢᱟᱜ ᱞᱟᱹᱭ ᱟᱠᱟᱱ ᱪᱟᱸᱫᱚ ᱨᱚᱪᱷᱟ ᱨᱮᱱᱟᱜ — ᱱᱟᱶᱟ ᱩᱫᱷᱟᱹᱨ ᱥᱟᱶ ᱥᱚᱱᱛᱚᱨ ᱵᱮᱵᱷᱟᱨ ᱢᱮ ᱾",
  "insight.txn-delivery-dependency": "ᱡᱚᱢᱟᱜ ᱰᱮᱞᱤᱵᱷᱟᱨᱤ ᱠᱷᱚᱨᱪᱟ ᱫᱚ ᱱᱤᱭᱟᱹ ᱦᱟᱯᱛᱟ ᱨᱮ ᱢᱟᱨᱟᱝ ᱦᱟᱹᱴᱤᱧ ᱠᱟᱱᱟ - ᱴᱮᱦᱟᱱᱰᱮᱱᱥᱤ ᱫᱚ ᱛᱷᱤᱨ ᱠᱟᱛᱮ ᱵᱟᱲᱦᱟᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.txn-health-spend-week": "ᱱᱤᱭᱟᱹ ᱦᱟᱯᱛᱟ ᱦᱚᱲᱢᱚ ᱥᱟᱶ ᱡᱚᱲᱟᱣ ᱠᱷᱚᱨᱪᱟ ᱵᱟᱲᱦᱟᱣ ᱮᱱᱟ - ᱡᱤᱣᱤᱫ ᱛᱟᱦᱮᱱ ᱨᱮᱭᱟᱜ ᱠᱷᱚᱨᱪᱟ ᱠᱷᱟᱴᱚ ᱚᱠᱛᱚ ᱨᱮᱭᱟᱜ ᱴᱟᱠᱟ ᱠᱮᱴᱮᱡ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.txn-discretionary-rise": "ᱢᱟᱲᱟᱝ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱛᱩᱞᱟᱹ ᱡᱚᱠᱷᱟ ᱨᱮ ᱫᱤᱱᱟᱹᱢ ᱵᱤᱪᱟᱹᱨ ᱠᱷᱚᱨᱪᱟ ᱵᱟᱲᱦᱟᱣ ᱮᱱᱟ ᱾",
  "insight.txn-lifestyle-stack": "ᱫᱚᱦᱲᱟ ᱛᱮ {merchant} ᱠᱷᱚᱨᱚᱪ ᱥᱟᱶ ᱱᱮᱛᱟᱨ ᱡᱤᱭᱚᱱ ᱦᱚᱨᱟ ᱠᱷᱚᱨᱪᱟ - ᱧᱮᱞ ᱫᱚᱦᱚ ᱚᱵᱷᱟᱨᱞᱮᱯ ᱾",
  "insight.txn-small-leaks": "ᱱᱤᱭᱟᱹ ᱦᱟᱯᱛᱟ ᱨᱮ ᱟᱭᱢᱟ ᱠᱟᱹᱴᱤᱡ ᱠᱤᱨᱤᱧ ᱠᱚ ᱵᱟᱹᱭ ᱵᱟᱹᱭ ᱛᱮ ᱪᱟᱸᱫᱚ ᱞᱟᱞᱠᱟᱣ ᱠᱚᱢ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.txn-daily-budget-cap": "ᱵᱤᱞ ᱠᱚ ᱫᱚ ᱟᱹᱨᱟᱹᱭ ᱨᱮᱭᱟᱜ ~{percent}% ᱵᱮᱵᱷᱟᱨ ᱮᱫᱟᱭ — ᱢᱩᱪᱟᱹᱫ ᱪᱟᱸᱫᱚ ᱞᱟᱹᱜᱤᱫ ᱡᱤᱭᱚᱱ ᱦᱚᱨᱟ ᱨᱮ ᱠᱷᱚᱨᱚᱪ ᱨᱮᱭᱟᱜ ᱡᱚᱥ ᱫᱚ {cap}/ᱫᱤᱱ ᱾",
  "insight.txn-daily-budget-room": "ᱵᱟᱹᱠᱛᱤ ᱛᱟᱭᱚᱢ, ᱱᱚᱣᱟ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱢᱩᱪᱟᱹᱫ ᱞᱟᱹᱜᱤᱫ {amount}/ᱫᱤᱱ ᱞᱟᱹᱵᱤᱫ ᱛᱟᱦᱮᱱᱟ ᱾",
  "insight.txn-recurring-growth-high": "ᱫᱚᱦᱲᱟ ᱫᱚᱦᱲᱟ ᱚᱯᱥᱚᱱᱟᱞ ᱠᱷᱚᱨᱪᱟ ᱵᱟᱹᱭ ᱵᱟᱹᱭ ᱛᱮ ᱵᱟᱲᱦᱟᱣᱜ ᱠᱟᱱᱟ - ᱠᱟᱹᱴᱤᱡ ᱫᱚᱦᱲᱟ ᱞᱟᱹᱵᱤᱫ ᱠᱚᱢ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.txn-recurring-growth": "ᱪᱟᱞᱟᱣᱮᱱ ᱪᱟᱸᱫᱚ ᱠᱚ ᱨᱮ ᱫᱚᱦᱲᱟ ᱫᱟᱭᱤᱠ ᱠᱚ ᱵᱟᱲᱦᱟᱣ ᱟᱠᱟᱱᱟ {percent}% ᱾",
  "insight.txn-under-pressure": "ᱵᱤᱪᱟᱹᱨ ᱞᱮᱠᱟᱛᱮ ᱫᱤᱱᱟᱹᱢ ᱠᱷᱚᱨᱚᱪ ᱡᱟᱹᱨᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱛᱤᱱ ᱨᱮ ᱫᱟᱭᱤᱠ ᱨᱮᱭᱟᱜ ᱪᱷᱟᱯ ᱞᱟᱦᱟ ᱠᱷᱚᱱ ᱜᱮ ᱪᱮᱛᱟᱱ ᱮᱱᱟ᱾",
  "insight.txn-rhythm-unsafe": "ᱦᱤᱡᱩᱜ ᱠᱟᱱ ᱦᱟᱯᱛᱟ ᱨᱮ ᱜᱟᱹᱦᱤᱨ ᱢᱟᱹᱦᱤᱛ ᱢᱮᱱᱟᱜᱼᱟ - ᱱᱚᱶᱟ ᱫᱚ ᱵᱟᱹᱲᱛᱤ ᱡᱷᱩᱠᱤ ᱴᱟᱠᱟ ᱡᱷᱚᱨᱠᱟ ᱞᱮᱠᱟ ᱵᱮᱵᱷᱟᱨ ᱢᱮ᱾",
  "insight.txn-rhythm-overlap": "ᱫᱚᱥᱟᱨ ᱦᱟᱯᱛᱟ ᱨᱮ ᱟᱭᱢᱟ ᱫᱟᱭᱤᱠ ᱠᱚ ᱚᱵᱷᱟᱨᱞᱮᱯ ᱢᱮ - ᱩᱱᱠᱩ ᱥᱴᱮᱠ ᱞᱟᱦᱟᱨᱮ ᱴᱟᱠᱟ ᱯᱚᱱᱛᱷᱟ ᱢᱮ ᱾",
  "insight.txn-rhythm-lifestyle": "ᱱᱮᱛᱟᱨ ᱫᱤᱱᱟᱹᱢ ᱠᱷᱚᱨᱚᱪ ᱠᱚᱢ ᱡᱤᱭᱚᱱ ᱦᱚᱨᱟ ᱦᱟᱢᱟᱞ - ᱵᱤᱪᱟᱹᱨ ᱥᱮᱛᱟᱜ ᱞᱟᱞᱠᱟᱣ ᱠᱚᱢ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.feed-restaurant-week": "ᱨᱮᱥᱴᱚᱨᱮᱱᱴ ᱟᱨ ᱰᱮᱞᱤᱵᱷᱟᱨᱤ ᱠᱷᱚᱨᱪᱟ ᱱᱤᱭᱟᱹ ᱦᱟᱯᱛᱟ ᱰᱷᱮᱨ ᱮᱱᱟ ᱾",
  "insight.feed-medical-month": "ᱱᱤᱭᱟᱹ ᱪᱟᱸᱫᱚ ᱨᱮ ᱪᱤᱠᱤᱥᱟ ᱠᱷᱚᱨᱪᱟ ᱥᱟᱫᱷᱟᱨᱚᱱ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱜᱮᱭᱟ ᱾",
  "narrative.strength.repaymentRhythm": "ᱪᱟᱞᱟᱣᱮᱱ ᱪᱟᱸᱫᱚ ᱠᱚ ᱨᱮ ᱥᱴᱮᱰᱤ ᱯᱩᱭᱥᱟᱹ ᱨᱩᱣᱟᱹᱲ ᱥᱟᱰᱮ",
