  "stability.headline.dualIncome": "ᱚᱲᱟᱜ ᱦᱚᱲ ᱠᱚ ᱢᱤᱫ ᱥᱟᱶᱛᱮ ᱟᱹᱭᱫᱟᱹᱨ ᱠᱚ ᱵᱮᱵᱷᱟᱨᱟ - ᱡᱟᱦᱟᱸ ᱥᱚᱛ ᱠᱷᱚᱱ ᱦᱚᱸ ᱦᱟᱨᱟᱣ ᱞᱮᱠᱷᱟᱱ ᱪᱷᱟᱯ ᱵᱟᱲᱦᱟᱣᱜᱼᱟ ᱾",
